-- Schedules and blackout windows (SCHED-001, CONTEXT_PACK §7, §8.6). Generated by `pnpm db:generate --name schedules`
-- from src/schema/schedules.ts, then reviewed. Forward-only: never edit once applied; add a new migration.
CREATE TABLE "blackout_windows" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"scope" text NOT NULL,
	"asset_ids" uuid[],
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"reason" text,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "blackout_windows_scope_check" CHECK ("blackout_windows"."scope" IN ('tenant', 'asset')),
	CONSTRAINT "blackout_windows_window_check" CHECK ("blackout_windows"."ends_at" > "blackout_windows"."starts_at"),
	CONSTRAINT "blackout_windows_scope_assets_check" CHECK (("blackout_windows"."scope" = 'tenant' AND "blackout_windows"."asset_ids" IS NULL) OR ("blackout_windows"."scope" = 'asset' AND coalesce(cardinality("blackout_windows"."asset_ids"), 0) >= 1)),
	CONSTRAINT "blackout_windows_reason_check" CHECK ("blackout_windows"."reason" IS NULL OR char_length("blackout_windows"."reason") <= 2000)
);
ALTER TABLE "blackout_windows" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "schedules" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"public_id" text NOT NULL,
	"name" text NOT NULL,
	"asset_ids" uuid[] NOT NULL,
	"sa_id" uuid NOT NULL,
	"mode" text NOT NULL,
	"objective" text,
	"cron_expr" text NOT NULL,
	"timezone" text NOT NULL,
	"overlap_policy" text DEFAULT 'skip' NOT NULL,
	"catch_up_policy" text DEFAULT 'skip' NOT NULL,
	"catch_up_window_minutes" integer DEFAULT 60 NOT NULL,
	"budgets" jsonb,
	"enabled" boolean DEFAULT true NOT NULL,
	"temporal_schedule_id" text,
	"last_fire_at" timestamp with time zone,
	"next_fire_at" timestamp with time zone,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "schedules_public_id_key" UNIQUE("public_id"),
	CONSTRAINT "schedules_name_check" CHECK (char_length("schedules"."name") BETWEEN 1 AND 200 AND length(btrim("schedules"."name")) > 0),
	CONSTRAINT "schedules_asset_ids_check" CHECK (cardinality("schedules"."asset_ids") >= 1),
	CONSTRAINT "schedules_mode_check" CHECK ("schedules"."mode" IN ('black', 'grey', 'white')),
	CONSTRAINT "schedules_overlap_policy_check" CHECK ("schedules"."overlap_policy" IN ('skip', 'buffer_one', 'cancel_other', 'allow')),
	CONSTRAINT "schedules_catch_up_policy_check" CHECK ("schedules"."catch_up_policy" IN ('skip', 'fire_once')),
	CONSTRAINT "schedules_catch_up_window_check" CHECK ("schedules"."catch_up_window_minutes" BETWEEN 0 AND 10080),
	CONSTRAINT "schedules_cron_expr_check" CHECK (char_length("schedules"."cron_expr") BETWEEN 1 AND 256),
	CONSTRAINT "schedules_timezone_check" CHECK (char_length("schedules"."timezone") BETWEEN 1 AND 64 AND length(btrim("schedules"."timezone")) > 0),
	CONSTRAINT "schedules_budgets_object_check" CHECK ("schedules"."budgets" IS NULL OR jsonb_typeof("schedules"."budgets") = 'object')
);
ALTER TABLE "schedules" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
-- Target of the tenant-scoped foreign key below: a schedule can only bind an SA of its own tenant (SCHED-001).
ALTER TABLE "standing_authorisations" ADD CONSTRAINT "standing_authorisations_tenant_id_id_key" UNIQUE("tenant_id","id");--> statement-breakpoint
-- NOT VALID (as verification_challenges, ASSET-001): "standing_authorisations" is FORCE RLS, so validating this
-- foreign key (a scan of that table as the owner) is refused. Inserts are still checked by the referential-integrity trigger.
ALTER TABLE "schedules" ADD CONSTRAINT "schedules_standing_authorisation_fk" FOREIGN KEY ("tenant_id","sa_id") REFERENCES "public"."standing_authorisations"("tenant_id","id") ON DELETE no action ON UPDATE no action NOT VALID;--> statement-breakpoint
CREATE INDEX "blackout_windows_tenant_window_idx" ON "blackout_windows" USING btree ("tenant_id","starts_at","ends_at");--> statement-breakpoint
