CREATE INDEX "schedules_asset_ids_gin_idx" ON "schedules" USING gin ("asset_ids");--> statement-breakpoint
CREATE POLICY "blackout_windows_tenant_isolation" ON "blackout_windows" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);--> statement-breakpoint
CREATE POLICY "schedules_tenant_isolation" ON "schedules" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);--> statement-breakpoint
-- Hand-written below (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor triggers). Reviewed.
-- FORCE: the owner role is subject to the tenant policy too, so nothing reads across tenants.
ALTER TABLE "schedules" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "blackout_windows" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- The runtime role gets DML only (no TRUNCATE, never PUBLIC). A schedule or window is removed by its own row, and
-- the policy still confines the delete to the active tenant.
REVOKE ALL ON "schedules", "blackout_windows" FROM PUBLIC;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "schedules", "blackout_windows" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with every update (bw_set_updated_at: 0002_column_mixins).
CREATE TRIGGER schedules_set_updated_at BEFORE UPDATE ON schedules FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();--> statement-breakpoint
CREATE TRIGGER blackout_windows_set_updated_at BEFORE UPDATE ON blackout_windows FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
